/**
 * WASM POC Loader
 * Loads and initializes the PugDB WASM module
 */

let wasmModule = null;
let wasmInstance = null;
let persistence = null;

/**
 * Initialize WASM module
 */
export async function initWASM() {
    if (wasmModule) {
        return wasmModule;
    }

    try {
        // Import WASM module (generated by wasm-pack)
        // Path: showcase/web/wasm-poc/f4kvs_wasm_poc.js (legacy filename, PugDB WASM)
        wasmModule = await import('./wasm-poc/f4kvs_wasm_poc.js');
        await wasmModule.default();
        
        console.log('✅ PugDB WASM POC loaded successfully');
        console.log('Note: This is a minimal POC implementation (not full pugdb-core)');
        return wasmModule;
    } catch (error) {
        console.error('❌ Failed to load WASM module:', error);
        console.warn('Falling back to simulation mode');
        return null;
    }
}

/**
 * Create a new PugDB instance using WASM
 * Note: WASM POC uses synchronous API (no async/await needed)
 * Also initializes IndexedDB persistence and loads saved data
 */
export async function createWASMInstance() {
    // Reuse existing instance if available
    if (wasmInstance) {
        return wasmInstance;
    }
    
    if (!wasmModule) {
        await initWASM();
    }

    if (!wasmModule || !wasmModule.F4KVS) {
        return null;
    }

    try {
        // POC uses synchronous constructor
        wasmInstance = new wasmModule.F4KVS();
        
        // Initialize persistence if available
        if (window.IndexedDBPersistence && !persistence) {
            persistence = new window.IndexedDBPersistence();
            try {
                await persistence.init();
                
                // Load saved data from IndexedDB
                if (persistence.isAvailable()) {
                    const loadedCount = await persistence.loadAll(wasmInstance);
                    if (loadedCount > 0) {
                        console.log(`📂 Restored ${loadedCount} key-value pair(s) from IndexedDB`);
                        // Store count for later display in terminal
                        persistence._loadedCount = loadedCount;
                    }
                }
            } catch (error) {
                console.warn('Failed to initialize persistence:', error);
            }
        }
        
        return wasmInstance;
    } catch (error) {
        console.error('Failed to create WASM instance:', error);
        return null;
    }
}

/**
 * Check if WASM is available
 */
export function isWASMAvailable() {
    return wasmModule !== null && wasmInstance !== null;
}

/**
 * Get WASM instance (if available)
 */
export function getWASMInstance() {
    return wasmInstance;
}

/**
 * Get persistence instance (if available)
 */
export function getPersistence() {
    return persistence;
}

// Debounce timer for auto-save
let saveTimer = null;
const SAVE_DEBOUNCE_MS = 500; // Wait 500ms after last operation before saving

/**
 * Save current WASM data to IndexedDB
 * Uses debouncing to avoid too many writes
 */
export async function saveToPersistence(immediate = false) {
    if (!persistence || !wasmInstance) {
        console.warn('Cannot save: persistence or WASM instance not available');
        return;
    }
    
    if (!persistence.isAvailable()) {
        console.warn('Cannot save: persistence not ready');
        return;
    }

    // Clear existing timer
    if (saveTimer) {
        clearTimeout(saveTimer);
        saveTimer = null;
    }

    // If immediate, save right away
    if (immediate) {
        try {
            const saved = await persistence.saveAll(wasmInstance);
            if (saved) {
                console.log('💾 Persistence saved immediately');
            }
        } catch (error) {
            console.error('Failed to save to persistence:', error);
        }
        return;
    }

    // Otherwise, debounce the save
    saveTimer = setTimeout(async () => {
        try {
            const saved = await persistence.saveAll(wasmInstance);
            if (saved) {
                console.log('💾 Persistence saved (debounced)');
            }
        } catch (error) {
            console.error('Failed to save to persistence:', error);
        }
        saveTimer = null;
    }, SAVE_DEBOUNCE_MS);
}

/**
 * Clear persisted data
 */
export async function clearPersistence() {
    if (persistence && persistence.isAvailable()) {
        await persistence.clear();
    }
}

// Save data when page becomes hidden (better than beforeunload)
document.addEventListener('visibilitychange', () => {
    if (document.hidden && persistence && wasmInstance && persistence.isAvailable()) {
        // Page is being hidden - save immediately
        persistence.saveAll(wasmInstance).catch(err => {
            console.warn('Failed to save on visibility change:', err);
        });
    }
});

// Also save on beforeunload as a fallback
window.addEventListener('beforeunload', () => {
    if (persistence && wasmInstance && persistence.isAvailable()) {
        // Try to save synchronously (browsers allow this in beforeunload)
        // Use sendBeacon or a synchronous approach if possible
        try {
            // Force immediate save - browsers may allow this
            persistence.saveAll(wasmInstance).catch(() => {
                // Ignore errors in beforeunload
            });
        } catch (err) {
            // Ignore errors in beforeunload
        }
    }
});

// Make available globally
window.initWASM = initWASM;
window.createWASMInstance = createWASMInstance;
window.isWASMAvailable = isWASMAvailable;
window.getWASMInstance = getWASMInstance;
window.getPersistence = getPersistence;
window.saveToPersistence = saveToPersistence;
window.clearPersistence = clearPersistence;
